<script setup>
import {computed,ref} from 'vue';
import {ElMessage} from 'element-plus';
import {wbRichContent,wbRichFromProduct} from '../../../../src/shared/wb-rich-content.js';
const props=defineProps({modelValue:Object,images:{type:Array,default:()=>[]},description:{type:String,default:''}}),emit=defineEmits(['update:modelValue']);
const tab=ref('edit');
const content=computed(()=>props.modelValue||{version:1,blocks:[]});
function update(index,change){const next=JSON.parse(JSON.stringify(content.value));Object.assign(next.blocks[index],change);emit('update:modelValue',next);}
function add(type){if(content.value.blocks.length>=10)return;emit('update:modelValue',{version:1,blocks:[...content.value.blocks,type==='text'?{type,text:''}:{type,url:''}]});}
function remove(index){emit('update:modelValue',{version:1,blocks:content.value.blocks.filter((_,i)=>i!==index)});}
function move(index,offset){const next=JSON.parse(JSON.stringify(content.value));[next.blocks[index],next.blocks[index+offset]]=[next.blocks[index+offset],next.blocks[index]];emit('update:modelValue',next);}
function fromProduct(){if(content.value.blocks.length)return;emit('update:modelValue',wbRichFromProduct(props.images,props.description));}
function download(){try{const value=wbRichContent(content.value),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='wb-rich-content-materials.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){ElMessage.error(e.message);}}
</script>
<template><div class="wb-rich-editor"><el-alert title="图文素材随 WB 草稿保存，可编辑、预览和导出；不是 Ozon JSON，不随商品卡 API 提交。WB 富文本需在商品发布后，到卖家后台编辑器完成发布。" type="info" :closable="false"/><el-tabs v-model="tab"><el-tab-pane label="编辑图文" name="edit"/><el-tab-pane label="效果预览" name="preview"/></el-tabs><template v-if="tab==='edit'"><div class="rich-actions"><el-button :disabled="content.blocks.length>=10" @click="add('image')">添加图片</el-button><el-button :disabled="content.blocks.length>=10" @click="add('text')">添加文本</el-button><el-button :disabled="!!content.blocks.length" @click="fromProduct">从当前图片和描述生成</el-button><el-button @click="download">导出素材清单</el-button><span>{{content.blocks.length}} / 10 区块</span></div><div v-for="(block,index) in content.blocks" :key="index" class="rich-block"><div class="rich-actions"><strong>{{index+1}}. {{block.type==='image'?'图片':'文本'}}</strong><el-button size="small" :disabled="index===0" @click="move(index,-1)">上移</el-button><el-button size="small" :disabled="index===content.blocks.length-1" @click="move(index,1)">下移</el-button><el-button size="small" type="danger" plain @click="remove(index)">删除</el-button></div><template v-if="block.type==='image'"><el-select :model-value="block.url" filterable clearable placeholder="选择当前商品图片" @update:model-value="update(index,{url:$event})"><el-option v-for="(url,i) in images" :key="url" :value="url" :label="`商品图片 ${i+1}`"/></el-select><el-input :model-value="block.url" placeholder="或填写 HTTPS 图片地址；上传图片可使用商品图片编辑器" @update:model-value="update(index,{url:$event})"/><el-image v-if="block.url" :src="block.url" :preview-src-list="[block.url]" preview-teleported fit="contain" class="rich-thumbnail"/></template><el-input v-else :model-value="block.text" type="textarea" :rows="4" maxlength="6000" show-word-limit @update:model-value="update(index,{text:$event})"/></div></template><div v-else class="rich-preview"><el-empty v-if="!content.blocks.length" description="尚未配置图文素材"/><template v-for="(block,index) in content.blocks" :key="index"><el-image v-if="block.type==='image'&&block.url" :src="block.url" :preview-src-list="content.blocks.filter(b=>b.type==='image'&&b.url).map(b=>b.url)" :initial-index="content.blocks.slice(0,index).filter(b=>b.type==='image'&&b.url).length" preview-teleported fit="contain"/><p v-else-if="block.type==='text'">{{block.text}}</p></template></div></div></template>
<style scoped>.wb-rich-editor{display:flex;flex-direction:column;gap:12px}.rich-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.rich-actions .el-button{margin-left:0}.rich-actions span{color:var(--el-text-color-secondary);font-size:12px}.rich-block{display:flex;flex-direction:column;gap:12px;padding:16px;border:1px solid var(--el-border-color);border-radius:8px}.rich-thumbnail{width:96px;height:126px}.rich-preview{max-width:600px;margin:auto;width:100%}.rich-preview .el-image{width:100%;display:block}.rich-preview p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}</style>
